using System;using Ashfall.Core;namespace Ashfall.Integration.Playable.HandsWeapons {public sealed class R24MeleeProfile {public readonly string Id,Name;public readonly int Catalog;public readonly Float3 Base,Tip;public R24MeleeProfile(string id,string name,int catalog,Float3 a,Float3 b){Id=id;Name=name;Catalog=catalog;Base=a;Tip=b;}} public static class R24MeleeProfiles {public static readonly R24MeleeProfile Knife=new R24MeleeProfile("knife","FIELD KNIFE",29,new Float3(0,.025f,-.025f),new Float3(0,.246f,-.025f));public static readonly R24MeleeProfile Katana=new R24MeleeProfile("katana","ASH KATANA",14,new Float3(0f,0.125f,-0.025f),new Float3(0f,1.11505739f,0.06807747501f));public static readonly R24MeleeProfile Excalibur=new R24MeleeProfile("excalibur","RIDGE EXCALIBUR",15,new Float3(0f,0.125f,-0.025f),new Float3(0f,1.11813253f,-0.025f));public static readonly R24MeleeProfile Cyberblade=new R24MeleeProfile("cyberblade","ARC CYBERBLADE",16,new Float3(0f,0.125f,-0.025f),new Float3(0f,1.11804522f,-0.009308173867f));public static R24MeleeProfile ForId(string id){return id=="knife"?Knife:id=="katana"?Katana:id=="excalibur"?Excalibur:id=="cyberblade"?Cyberblade:null;}}}
